  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`transport_origin_id`) REFERENCES `transport_origins` (`transport_origin_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`assigned_staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE SET NULL ON UPDATE CASCADE,
